#include "unity.h"
#include "buffer.h"
#include "helpers.h"
#include "malloc_wrap.h"

void setUp(void) { }
void tearDown(void) { malloc_reset(); }

void unit_test_buffer_compact_calloc_failure(void) {
    // Setup: create a buffer with some content and extra capacity
    buffer_t *buf = helper_create_buffer_with_content("hello world");
    TEST_ASSERT_NOT_NULL(buf);

    // Artificially increase buffer size to ensure there is unused space
    // (simulate a buffer with extra capacity)
    size_t old_size = 32;
    int resize_result = buffer_resize(buf, old_size);
    TEST_ASSERT_EQUAL_INT(0, resize_result);
    helper_assert_buffer_size(buf, old_size);
    helper_assert_buffer_content(buf, "hello world");

    // Set up malloc_wrap to fail the next allocation (calloc in buffer_compact)
    malloc_fail_after(2); // 2 allocations in setup: helper_create_buffer_with_content (2 allocs)

    // Test: buffer_compact should fail due to calloc failure
    ssize_t result = buffer_compact(buf);
    TEST_ASSERT_EQUAL_INT(-1, result);

    // Buffer should remain unchanged
    helper_assert_buffer_content(buf, "hello world");
    helper_assert_buffer_size(buf, old_size);

    // Cleanup
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_compact_calloc_failure);
    return UNITY_END();
}


